import { existsSync, statSync } from "node:fs";
import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import type { ClassifyCommand } from "../domain/commands.js";
import type { CategoryMatch } from "../domain/entities.js";
import type { CategoryStore, EmbeddingClient } from "../domain/ports.js";

export class ClassifyDocumentUseCase {
  constructor(
    private readonly embeddings: EmbeddingClient,
    private readonly categories: CategoryStore,
  ) {}

  async execute(command: ClassifyCommand): Promise<CategoryMatch[]> {
    const content = await readInput(command.input);
    const embedding = await this.embeddings.embed(content);
    return this.categories.search(embedding, command.limit);
  }
}

export async function readInput(input: string): Promise<string> {
  const filePath = resolveReadablePath(input);

  if (filePath) {
    return readFile(filePath, "utf8");
  }

  if (isHttpUrl(input)) {
    const response = await fetch(input);

    if (!response.ok) {
      throw new Error(`Unable to fetch URL content: ${response.status} ${response.statusText}`);
    }

    return await response.text();
  }

  return input;
}

function resolveReadablePath(input: string): string | undefined {
  const candidates = [input];

  const initCwd = process.env.INIT_CWD;
  if (initCwd) {
    candidates.push(resolve(initCwd, input));
  }

  for (const candidate of candidates) {
    if (!existsSync(candidate)) {
      continue;
    }

    const stat = statSync(candidate);
    if (stat.isFile()) {
      return candidate;
    }

    if (stat.isDirectory()) {
      throw new Error(`Input path is a directory, expected a file: ${candidate}`);
    }
  }

  return undefined;
}

function isHttpUrl(value: string): boolean {
  return /^https?:\/\//i.test(value);
}

import type { FindCommand } from "../domain/commands.js";
import type { FindResult } from "../domain/entities.js";
import type { VectorStore } from "../domain/ports.js";

export class FindDocumentsUseCase {
  constructor(private readonly store: VectorStore) {}

  async execute(command: FindCommand): Promise<FindResult> {
    validateFilters(command);
    return this.store.find({
      file: command.file,
      text: command.text,
      category: command.category,
      limit: command.limit,
      offset: command.offset,
    });
  }
}

function validateFilters(command: FindCommand): void {
  if (!command.file && !command.text && !command.category) {
    throw new Error("find requires at least one filter: --file, --text, or --category");
  }

  if (!Number.isInteger(command.limit) || command.limit < 0) {
    throw new Error("find limit must be a non-negative integer");
  }

  if (!Number.isInteger(command.offset) || command.offset < 0) {
    throw new Error("find offset must be a non-negative integer");
  }
}

import type { IndexDocumentCommand } from "../domain/commands.js";
import type { DocumentChunk, IndexDocumentResult } from "../domain/entities.js";
import type { CategoryStore, EmbeddingClient, VectorStore } from "../domain/ports.js";
import { noopProgressReporter, type ProgressReporter } from "../shared/progress.js";
import { chunkText } from "../shared/chunk-text.js";
import { readInput } from "./classify-document.js";

export class IndexDocumentUseCase {
  constructor(
    private readonly embeddings: EmbeddingClient,
    private readonly store: VectorStore,
    private readonly categories: CategoryStore,
  ) {}

  async execute(command: IndexDocumentCommand, progress: ProgressReporter = noopProgressReporter): Promise<IndexDocumentResult> {
    const content = await readInput(command.input);
    const chunks = chunkText(content);

    if (chunks.length === 0) {
      throw new Error("Cannot index document: input did not contain any non-empty chunks");
    }

    progress.start(chunks.length);

    const chunksToInsert: DocumentChunk[] = [];

    let processed = 0;

    for (const chunk of chunks) {
      const chunkEmbedding = await this.embeddings.embed(chunk.content);
      const [bestMatch] = await this.categories.search(chunkEmbedding, 1);

      if (!bestMatch) {
        throw new Error("Cannot index document: categories database is empty. Run `rag-cli categories sync <categories.yml>` first.");
      }

      chunksToInsert.push({
        source: command.input,
        content: chunk.content,
        embedding: chunkEmbedding,
        taxonomy: {
          category: bestMatch.category.id,
          taxonomy: bestMatch.category.path,
          description: bestMatch.category.description,
          metadata: {
            ...command.metadata,
            chunkIndex: chunk.chunkIndex,
            chunkCount: chunk.chunkCount,
            chunkStart: chunk.chunkStart,
            chunkEnd: chunk.chunkEnd,
            categoryScore: bestMatch.score,
          },
        },
      });

      processed += 1;
      progress.update(processed, chunks.length);
    }

    const ids = await this.store.addMany(chunksToInsert);

    progress.done(chunks.length);

    return {
      chunks: chunks.length,
      ids,
    };
  }
}

import type { SearchCommand } from "../domain/commands.js";
import type { SearchMatch } from "../domain/entities.js";
import type { EmbeddingClient, VectorStore } from "../domain/ports.js";

export class SearchDocumentsUseCase {
  constructor(
    private readonly embeddings: EmbeddingClient,
    private readonly store: VectorStore,
  ) {}

  async execute(command: SearchCommand): Promise<SearchMatch[]> {
    const embedding = await this.embeddings.embed(command.text);
    return this.store.search(embedding, command.limit);
  }
}

import type { TaxonomySyncCommand } from "../domain/commands.js";
import type { EmbeddingClient, CategoryStore } from "../domain/ports.js";
import { noopProgressReporter, type ProgressReporter } from "../shared/progress.js";
import { loadTaxonomyFile } from "../infrastructure/taxonomy/yaml-taxonomy-loader.js";

export class TaxonomySyncUseCase {
  constructor(
    private readonly embeddings: EmbeddingClient,
    private readonly categories: CategoryStore,
  ) {}

  async execute(command: TaxonomySyncCommand, progress: ProgressReporter = noopProgressReporter): Promise<number> {
    const taxonomyCategories = await loadTaxonomyFile(command.taxonomyFile);
    progress.start(taxonomyCategories.length);

    let processed = 0;
    for (const category of taxonomyCategories) {
      await this.categories.upsert(category, await this.embeddings.embed(categoryEmbeddingText(category)));
      processed += 1;
      progress.update(processed, taxonomyCategories.length);
    }

    progress.done(taxonomyCategories.length);
    return taxonomyCategories.length;
  }
}

export function categoryEmbeddingText(category: {
  id: string;
  path: string;
  description?: string;
  examples: string[];
}): string {
  return [
    `Category id: ${category.id}`,
    `Path: ${category.path}`,
    category.description ? `Description: ${category.description}` : undefined,
    category.examples.length > 0 ? `Examples: ${category.examples.join("; ")}` : undefined,
  ]
    .filter(Boolean)
    .join("\n");
}

import { Command } from "commander";
import type { Metadata } from "../domain/entities.js";

export interface CommonOptions {
  db?: string;
  categoriesDb?: string;
  embeddingUrl?: string;
  envFile?: string;
}

export interface CliApp {
  syncTaxonomy(command: { taxonomyFile: string }): Promise<number>;
  classify(command: { input: string; limit: number }): Promise<unknown>;
  indexDocument(command: { input: string; metadata: Metadata }): Promise<unknown>;
  stats(): Promise<unknown>;
  find(command: { file?: string; text?: string; category?: string; limit: number; offset: number }): Promise<unknown>;
  search(command: { text: string; limit: number }): Promise<unknown>;
}

export type AppFactory = (options: CommonOptions) => Promise<CliApp> | CliApp;

interface ClassifyOptions extends CommonOptions {
  limit?: string;
}

interface IndexOptions extends CommonOptions {
  metadata?: string;
}

interface FindOptions extends CommonOptions {
  file?: string;
  text?: string;
  category?: string;
  limit?: string;
  offset?: string;
}

interface SearchOptions extends CommonOptions {
  limit?: string;
}

export function buildProgram(createApp: AppFactory = defaultCreateApp): Command {
  const program = new Command();

  program
    .name("rag-cli")
    .description("Sync taxonomy categories, index categorized content, and search nearest occurrences using embeddings")
    .version("1.0.0")
    .option("--db <path>", "SQLite documents database path")
    .option("--categories-db <path>", "SQLite categories database path")
    .option("--embedding-url <url>", "POST /embedding endpoint URL")
    .option("--env-file <path>", ".env file path", ".env");

  const categories = program.command("categories").description("Manage the categories embedding database");

  categories
    .command("sync")
    .description("Read the source-of-truth categories.yml and upsert category embeddings")
    .argument("<taxonomy-file>", "Taxonomy YAML file, for example assets/taxonomy/categories.yml")
    .action(async (taxonomyFile: string, options: CommonOptions) => {
      const app = await createApp(resolveCommonOptions(program, options));
      const count = await app.syncTaxonomy({ taxonomyFile });
      console.log(JSON.stringify({ categories: count }, null, 2));
    });

  program
    .command("classify")
    .description("Classify text/file against the already-synced categories database")
    .argument("<input>", "Text to classify, or a file path")
    .option("-l, --limit <number>", "Maximum category matches", "5")
    .action(async (input: string, options: ClassifyOptions) => {
      const app = await createApp(resolveCommonOptions(program, options));
      const matches = await app.classify({
        input,
        limit: Number.parseInt(options.limit ?? "5", 10),
      });
      console.log(JSON.stringify(matches, null, 2));
    });

  program
    .command("index")
    .description("Embed and persist text/file with user metadata and the best category from the categories DB")
    .argument("<input>", "Text to index, or a file path")
    .option("-m, --metadata <json>", "Additional JSON metadata", "{}")
    .action(async (input: string, options: IndexOptions) => {
      const app = await createApp(resolveCommonOptions(program, options));
      const result = await app.indexDocument({
        input,
        metadata: parseMetadata(options.metadata),
      });
      console.log(JSON.stringify(result, null, 2));
    });

  program
    .command("stats")
    .alias("inspect")
    .description("Show database stats for documents and categories")
    .action(async (options: CommonOptions) => {
      const app = await createApp(resolveCommonOptions(program, options));
      const stats = await app.stats();
      console.log(JSON.stringify(stats, null, 2));
    });

  program
    .command("find")
    .description("Filter indexed documents and chunks by file, text, or category")
    .option("--file <value>", "Filter by source file/path")
    .option("--text <value>", "Filter by stored text content")
    .option("--category <value>", "Filter by category id or name")
    .option("-l, --limit <number>", "Maximum matches", "20")
    .option("-o, --offset <number>", "Result offset", "0")
    .action(async (options: FindOptions) => {
      validateFindOptions(options);
      const app = await createApp(resolveCommonOptions(program, options));
      const result = await app.find({
        file: options.file,
        text: options.text,
        category: options.category,
        limit: Number.parseInt(options.limit ?? "20", 10),
        offset: Number.parseInt(options.offset ?? "0", 10),
      });
      console.log(JSON.stringify(result, null, 2));
    });

  program
    .command("search")
    .description("Embed text and return nearest stored occurrences sorted by similarity")
    .argument("<text>", "Search text")
    .option("-l, --limit <number>", "Maximum matches", "10")
    .action(async (text: string, options: SearchOptions) => {
      const app = await createApp(resolveCommonOptions(program, options));
      const matches = await app.search({ text, limit: Number.parseInt(options.limit ?? "10", 10) });
      console.log(JSON.stringify(matches, null, 2));
    });

  return program;
}

function resolveCommonOptions(program: Command, options: CommonOptions): CommonOptions {
  const globalOptions = program.opts<CommonOptions>();
  return {
    db: options.db ?? globalOptions.db,
    categoriesDb: options.categoriesDb ?? globalOptions.categoriesDb,
    embeddingUrl: options.embeddingUrl ?? globalOptions.embeddingUrl,
    envFile: options.envFile ?? globalOptions.envFile,
  };
}

export function parseMetadata(value = "{}"): Metadata {
  const parsed = JSON.parse(value) as unknown;

  if (!parsed || Array.isArray(parsed) || typeof parsed !== "object") {
    throw new Error("--metadata must be a JSON object");
  }

  return parsed as Metadata;
}

function validateFindOptions(options: FindOptions): void {
  if (!options.file && !options.text && !options.category) {
    throw new Error("find requires at least one filter: --file, --text, or --category");
  }
}

async function defaultCreateApp(options: CommonOptions): Promise<CliApp> {
  const { createApp } = await import("../core/core.js");
  return createApp(options) as unknown as CliApp;
}

import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";

export interface AppConfig {
  databasePath: string;
  categoriesDatabasePath: string;
  embeddingEndpoint: string;
  embeddingProvider: string;
  embeddingModel: string;
  embeddingDimensions: number;
}

export interface ConfigOptions {
  db?: string;
  categoriesDb?: string;
  embeddingUrl?: string;
  embeddingProvider?: string;
  embeddingModel?: string;
  embeddingDimensions?: string;
  envFile?: string;
}

const loadedEnvFiles = new Set<string>();

export function buildConfig(options: ConfigOptions): AppConfig {
  loadEnvFile(options.envFile);

  const embeddingDimensionsRaw = options.embeddingDimensions ?? process.env.RAG_CLI_EMBEDDING_DIMENSIONS ?? "";
  const embeddingDimensions = Number.parseInt(embeddingDimensionsRaw, 10);

  if (!Number.isFinite(embeddingDimensions) || embeddingDimensions <= 0) {
    throw new Error("RAG_CLI_EMBEDDING_DIMENSIONS must be a positive integer");
  }

  return {
    databasePath: options.db ?? process.env.RAG_CLI_DB ?? "./rag.sqlite",
    categoriesDatabasePath: options.categoriesDb ?? process.env.RAG_CLI_CATEGORIES_DB ?? "./rag-categories.sqlite",
    embeddingEndpoint: options.embeddingUrl ?? process.env.RAG_CLI_EMBEDDING_URL ?? "http://localhost:3000/embedding",
    embeddingProvider: options.embeddingProvider ?? process.env.RAG_CLI_EMBEDDING_PROVIDER ?? "unknown",
    embeddingModel: options.embeddingModel ?? process.env.RAG_CLI_EMBEDDING_MODEL ?? "unknown",
    embeddingDimensions,
  };
}

export function loadEnvFile(envFile = ".env"): void {
  const absolutePath = resolve(process.cwd(), envFile);

  if (loadedEnvFiles.has(absolutePath)) {
    return;
  }

  loadedEnvFiles.add(absolutePath);

  if (!existsSync(absolutePath)) {
    return;
  }

  const variables = parseEnvFile(readFileSync(absolutePath, "utf8"));

  for (const [key, value] of Object.entries(variables)) {
    process.env[key] ??= value;
  }
}

function parseEnvFile(contents: string): Record<string, string> {
  const variables: Record<string, string> = {};

  for (const rawLine of contents.replace(/^\uFEFF/, "").split(/\r?\n/)) {
    const line = rawLine.trim();

    if (!line || line.startsWith("#")) {
      continue;
    }

    const match = /^(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/.exec(line);

    if (!match) {
      continue;
    }

    variables[match[1]] = parseEnvValue(match[2]);
  }

  return variables;
}

function parseEnvValue(rawValue: string): string {
  const value = rawValue.trim();
  const quote = value[0];

  if ((quote === '"' || quote === "'") && value.endsWith(quote)) {
    const unquoted = value.slice(1, -1);

    if (quote === '"') {
      return unquoted.replace(/\\([nrt"\\])/g, (_, escaped: string) => {
        switch (escaped) {
          case "n":
            return "\n";
          case "r":
            return "\r";
          case "t":
            return "\t";
          default:
            return escaped;
        }
      });
    }

    return unquoted;
  }

  return value.replace(/\s+#.*$/, "").trim();
}

import { ClassifyDocumentUseCase } from "../application/classify-document.js";
import { FindDocumentsUseCase } from "../application/find-documents.js";
import { IndexDocumentUseCase } from "../application/index-document.js";
import { SearchDocumentsUseCase } from "../application/search-documents.js";
import { StatsUseCase } from "../application/stats.js";
import { TaxonomySyncUseCase } from "../application/taxonomy-sync.js";
import { buildConfig, type AppConfig, type ConfigOptions } from "../config/config.js";
import type { ClassifyCommand, FindCommand, IndexDocumentCommand, SearchCommand, TaxonomySyncCommand } from "../domain/commands.js";
import type { AppStats, CategoryMatch, FindResult, IndexDocumentResult, SearchMatch } from "../domain/entities.js";
import { SqliteCategoryStore } from "../infrastructure/database/sqlite-category-store.js";
import { SqliteVectorStore } from "../infrastructure/database/sqlite-vector-store.js";
import { HttpEmbeddingClient } from "../infrastructure/embedding/http-embedding-client.js";
import { createStderrProgressReporter } from "../shared/progress.js";

export class RagCliApp {
  constructor(private readonly config: AppConfig) {}

  async syncTaxonomy(command: TaxonomySyncCommand): Promise<number> {
    const { store, categories, embeddings } = await this.dependencies();
    try {
      return await new TaxonomySyncUseCase(embeddings, categories).execute(command, createStderrProgressReporter("Syncing categories"));
    } finally {
      await Promise.all([store.close(), categories.close()]);
    }
  }

  async classify(command: ClassifyCommand): Promise<CategoryMatch[]> {
    const { store, categories, embeddings } = await this.dependencies();
    try {
      return await new ClassifyDocumentUseCase(embeddings, categories).execute(command);
    } finally {
      await Promise.all([store.close(), categories.close()]);
    }
  }

  async indexDocument(command: IndexDocumentCommand): Promise<IndexDocumentResult> {
    const { store, categories, embeddings } = await this.dependencies();
    try {
      return await new IndexDocumentUseCase(embeddings, store, categories).execute(command, createStderrProgressReporter("Indexing chunks"));
    } finally {
      await Promise.all([store.close(), categories.close()]);
    }
  }

  async stats(): Promise<AppStats> {
    const { store, categories } = await this.storeDependencies();
    try {
      return await new StatsUseCase(store, categories, this.config.databasePath, this.config.categoriesDatabasePath).execute();
    } finally {
      await Promise.all([store.close(), categories.close()]);
    }
  }

  async find(command: FindCommand): Promise<FindResult> {
    const { store } = await this.vectorStore();
    try {
      return await new FindDocumentsUseCase(store).execute(command);
    } finally {
      await store.close();
    }
  }

  async search(command: SearchCommand): Promise<SearchMatch[]> {
    const { store, categories, embeddings } = await this.dependencies();
    try {
      return await new SearchDocumentsUseCase(embeddings, store).execute(command);
    } finally {
      await Promise.all([store.close(), categories.close()]);
    }
  }

  private async dependencies(): Promise<{
    store: SqliteVectorStore;
    categories: SqliteCategoryStore;
    embeddings: HttpEmbeddingClient;
  }> {
    const metadata = {
      embedding_provider: this.config.embeddingProvider,
      embedding_url: this.config.embeddingEndpoint,
      embedding_model: this.config.embeddingModel,
      embedding_dimensions: String(this.config.embeddingDimensions),
    };

    const store = new SqliteVectorStore(this.config.databasePath, metadata);
    const categories = new SqliteCategoryStore(this.config.categoriesDatabasePath, metadata);
    await Promise.all([store.init(), categories.init()]);

    return {
      store,
      categories,
      embeddings: new HttpEmbeddingClient(this.config.embeddingEndpoint),
    };
  }

  private async storeDependencies(): Promise<{
    store: SqliteVectorStore;
    categories: SqliteCategoryStore;
  }> {
    const metadata = {
      embedding_provider: this.config.embeddingProvider,
      embedding_url: this.config.embeddingEndpoint,
      embedding_model: this.config.embeddingModel,
      embedding_dimensions: String(this.config.embeddingDimensions),
    };

    const store = new SqliteVectorStore(this.config.databasePath, metadata);
    const categories = new SqliteCategoryStore(this.config.categoriesDatabasePath, metadata);
    await Promise.all([store.init(), categories.init()]);

    return { store, categories };
  }

  private async vectorStore(): Promise<{ store: SqliteVectorStore }> {
    const metadata = {
      embedding_provider: this.config.embeddingProvider,
      embedding_url: this.config.embeddingEndpoint,
      embedding_model: this.config.embeddingModel,
      embedding_dimensions: String(this.config.embeddingDimensions),
    };

    const store = new SqliteVectorStore(this.config.databasePath, metadata);
    await store.init();
    return { store };
  }
}

export function createApp(options: ConfigOptions): RagCliApp {
  return new RagCliApp(buildConfig(options));
}

