export class SqliteVectorStore implements VectorStore {
  private db?: Database<sqlite3.Database, sqlite3.Statement>;
  private dimensions = 0;

  constructor(
    private readonly filename: string,
    private readonly metadata: IndexMetadata,
  ) {}

  async init(): Promise<void> {
    this.db = await open({ filename: this.filename, driver: sqlite3.Database });

    await this.db.exec(`
      CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        source TEXT NOT NULL,
        content TEXT NOT NULL,
        category TEXT NOT NULL,
        taxonomy TEXT NOT NULL,
        description TEXT,
        metadata_json TEXT NOT NULL,
        embedding_json TEXT NOT NULL,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

      CREATE INDEX IF NOT EXISTS idx_documents_category ON documents(category);
      CREATE INDEX IF NOT EXISTS idx_documents_taxonomy ON documents(taxonomy);
      CREATE INDEX IF NOT EXISTS idx_documents_source ON documents(source);
    `);

    await ensureIndexMetadata(this.db, this.metadata, "documents index");

    this.dimensions = parseDimensions(this.metadata);

    loadSqliteVec(this.db);

    await this.db.exec(`
      CREATE VIRTUAL TABLE IF NOT EXISTS documents_vec
      USING vec0(embedding float[${this.dimensions}]);
    `);
  }

  async add(chunk: DocumentChunk): Promise<number> {
    const [id] = await this.addMany([chunk]);
    return id ?? 0;
  }

  async addMany(chunks: DocumentChunk[]): Promise<number[]> {
    const db = this.ensureDb();
    const ids: number[] = [];

    await db.exec("BEGIN");
    try {
      for (const chunk of chunks) {
        const embedding = normalizeEmbedding(chunk.embedding, this.dimensions);

        const result = await db.run(
          `INSERT INTO documents
            (source, content, category, taxonomy, description, metadata_json, embedding_json)
           VALUES (?, ?, ?, ?, ?, ?, ?)`,
          chunk.source,
          chunk.content,
          chunk.taxonomy.category,
          chunk.taxonomy.taxonomy,
          chunk.taxonomy.description ?? null,
          JSON.stringify(chunk.taxonomy.metadata),
          JSON.stringify(chunk.embedding),
        );

        const id = result.lastID ?? 0;
        ids.push(id);
        await db.run(`INSERT INTO documents_vec(rowid, embedding) VALUES (?, vec_f32(?))`, id, JSON.stringify(embedding));
      }

      await db.exec("COMMIT");
      return ids;
    } catch (error) {
      await db.exec("ROLLBACK");
      throw error;
    }
  }

  async search(queryEmbedding: number[], limit: number): Promise<SearchMatch[]> {
    const db = this.ensureDb();
    const normalized = normalizeEmbedding(queryEmbedding, this.dimensions);

    const knn = await db.all<Array<{ rowid: number; distance: number }>>(
      `SELECT rowid, distance
       FROM documents_vec
       WHERE embedding MATCH vec_f32(?)
       ORDER BY distance ASC
       LIMIT ?`,
      JSON.stringify(normalized),
      limit,
    );

    if (knn.length === 0) {
      return [];
    }

    knn.sort((left, right) => left.distance - right.distance || left.rowid - right.rowid);

    const ids = knn.map((row) => row.rowid);
    const placeholders = ids.map(() => "?").join(",");
    const docs = await db.all<StoredRow[]>(`SELECT * FROM documents WHERE id IN (${placeholders})`, ...ids);
    const docsById = new Map(docs.map((row) => [row.id, row] as const));

    return knn
      .map(({ rowid, distance }) => {
        const row = docsById.get(rowid);
        if (!row) {
          return undefined;
        }
        return this.toSearchMatch({ ...row, distance } as KnnRow);
      })
      .filter((match): match is SearchMatch => Boolean(match));
  }

  async find(filters: FindFilters): Promise<FindResult> {
    const db = this.ensureDb();
    const where = buildWhereClause(filters);
    const params = buildParams(filters);
    const totalRow = await db.get<CountRow>(`SELECT count(*) AS count FROM documents${where.sql}`, params);
    const rows = await db.all<StoredRow[]>(
      `SELECT * FROM documents${where.sql} ORDER BY id ASC LIMIT ? OFFSET ?`,
      ...params,
      filters.limit,
      filters.offset,
    );

    return {
      total: totalRow?.count ?? 0,
      limit: filters.limit,
      offset: filters.offset,
      matches: rows.map((row) => this.toFindMatch(row)),
    };
  }

  async stats(): Promise<DocumentStats> {
    const db = this.ensureDb();
    const [chunksRow, sourcesRow, categoriesRow, byCategoryRows] = await Promise.all([
      db.get<CountRow>(`SELECT count(*) AS count FROM documents`),
      db.get<CountRow>(`SELECT count(DISTINCT source) AS count FROM documents`),
      db.get<CountRow>(`SELECT count(DISTINCT category) AS count FROM documents`),
      db.all<ByCategoryRow[]>(`SELECT category, count(*) AS chunks FROM documents GROUP BY category ORDER BY chunks DESC, category ASC`),
    ]);

    return {
      chunks: chunksRow?.count ?? 0,
      sources: sourcesRow?.count ?? 0,
      categories: categoriesRow?.count ?? 0,
      byCategory: byCategoryRows.map((row) => ({ category: row.category, chunks: row.chunks })),
    };
  }

  async close(): Promise<void> {
    await this.db?.close();
    this.db = undefined;
  }

  private ensureDb(): Database<sqlite3.Database, sqlite3.Statement> {
    if (!this.db) {
      throw new Error("Vector store is not initialized");
    }

    return this.db;
  }

  private toSearchMatch(row: KnnRow): SearchMatch {
    const taxonomy: TaxonomyEntry = {
      category: row.category,
      taxonomy: row.taxonomy,
      description: row.description ?? undefined,
      metadata: JSON.parse(row.metadata_json) as TaxonomyEntry["metadata"],
    };

    return {
      id: row.id,
      source: row.source,
      content: row.content,
      taxonomy,
      score: l2DistanceToCosineSimilarity(row.distance),
    };
  }

  private toFindMatch(row: StoredRow): FindMatch {
    const taxonomy: TaxonomyEntry = {
      category: row.category,
      taxonomy: row.taxonomy,
      description: row.description ?? undefined,
      metadata: JSON.parse(row.metadata_json) as TaxonomyEntry["metadata"],
    };

    return {
      id: row.id,
      source: row.source,
      content: row.content,
      taxonomy,
    };
  }
}

function parseDimensions(metadata: IndexMetadata): number {
  const raw = metadata.embedding_dimensions;
  const value = Number.parseInt(raw ?? "", 10);

  if (!Number.isFinite(value) || value <= 0) {
    throw new Error("documents index metadata is missing a valid embedding_dimensions");
  }

  return value;
}

function normalizeEmbedding(values: number[], dimensions: number): number[] {
  if (values.length !== dimensions) {
    throw new Error(`Embedding dimension mismatch: expected ${dimensions} values but received ${values.length}`);
  }

  let norm = 0;
  for (const value of values) {
    norm += value * value;
  }

  if (norm === 0) {
    return values.slice();
  }

  const scale = 1 / Math.sqrt(norm);
  return values.map((value) => value * scale);
}

function l2DistanceToCosineSimilarity(distance: number): number {
  // For unit-normalized vectors: ||a-b||^2 = 2 - 2cos(a,b)  => cos = 1 - d^2/2
  const similarity = 1 - (distance * distance) / 2;
  return Math.max(-1, Math.min(1, similarity));
}

function buildWhereClause(filters: FindFilters): { sql: string } {
  const clauses = buildClauses(filters);
  return { sql: clauses.length > 0 ? ` WHERE ${clauses.join(" AND ")}` : "" };
}

function buildClauses(filters: Pick<FindFilters, "file" | "text" | "category">): string[] {
  const clauses: string[] = [];

  if (filters.file) {
    clauses.push(`lower(source) LIKE ? ESCAPE '\\'`);
  }

  if (filters.text) {
    clauses.push(`lower(content) LIKE ? ESCAPE '\\'`);
  }

  if (filters.category) {
    clauses.push(`lower(category) LIKE ? ESCAPE '\\'`);
  }

  return clauses;
}

function buildParams(filters: FindFilters): string[] {
  const params: string[] = [];

  if (filters.file) {
    params.push(toLikePattern(filters.file));
  }

  if (filters.text) {
    params.push(toLikePattern(filters.text));
  }

  if (filters.category) {
    params.push(toLikePattern(filters.category));
  }

  return params;
}

function toLikePattern(value: string): string {
  return `%${escapeLike(value.toLowerCase())}%`;
}

function escapeLike(value: string): string {
  return value.replace(/[\\%_]/g, (character) => `\\${character}`);
}

import { readFile } from "node:fs/promises";
import type { CategoryEntry } from "../../domain/entities.js";

interface MutableCategoryEntry {
  id?: string;
  path?: string;
  description?: string;
  examples: string[];
}

export async function loadTaxonomyFile(file: string): Promise<CategoryEntry[]> {
  const contents = await readFile(file, "utf8");
  return parseTaxonomyYaml(contents);
}

export function parseTaxonomyYaml(contents: string): CategoryEntry[] {
  const categories: MutableCategoryEntry[] = [];
  let current: MutableCategoryEntry | undefined;
  let inCategories = false;
  let inExamples = false;

  for (const rawLine of contents.split(/\r?\n/)) {
    const withoutComment = rawLine.replace(/\s+#.*$/, "");
    const line = withoutComment.trim();

    if (!line) {
      continue;
    }

    if (line === "categories:") {
      inCategories = true;
      continue;
    }

    if (!inCategories) {
      continue;
    }

    if (line.startsWith("- id:")) {
      current = { id: parseScalar(line.slice("- id:".length)), examples: [] };
      categories.push(current);
      inExamples = false;
      continue;
    }

    if (!current) {
      continue;
    }

    if (line.startsWith("path:")) {
      current.path = parseScalar(line.slice("path:".length));
      inExamples = false;
      continue;
    }

    if (line.startsWith("description:")) {
      current.description = parseScalar(line.slice("description:".length));
      inExamples = false;
      continue;
    }

    if (line === "examples:") {
      inExamples = true;
      continue;
    }

    if (inExamples && line.startsWith("- ")) {
      current.examples.push(parseScalar(line.slice(2)));
    }
  }

  return categories.map((category, index) => {
    if (!category.id || !category.path) {
      throw new Error(`Invalid taxonomy category at index ${index}: id and path are required`);
    }

    return {
      id: category.id,
      path: category.path,
      description: category.description,
      examples: category.examples,
    };
  });
}

function parseScalar(value: string): string {
  const trimmed = value.trim();
  const quote = trimmed[0];

  if ((quote === '"' || quote === "'") && trimmed.endsWith(quote)) {
    return trimmed.slice(1, -1);
  }

  return trimmed;
}

export interface TextChunk {
  content: string;
  chunkIndex: number;
  chunkCount: number;
  chunkStart: number;
  chunkEnd: number;
}

export interface ChunkTextOptions {
  maxChunkSize?: number;
  minChunkSize?: number;
}

// Target: ~1000-1200 chars.
const DEFAULT_MAX_CHUNK_SIZE = 1_200;
// Minimum useful chunk size: avoid one-liners.
const DEFAULT_MIN_CHUNK_SIZE = 250;
const MIN_SPLIT_SIZE = 400;

export function chunkText(input: string, options: ChunkTextOptions = {}): TextChunk[] {
  const maxChunkSize = options.maxChunkSize ?? DEFAULT_MAX_CHUNK_SIZE;
  const minChunkSize = options.minChunkSize ?? DEFAULT_MIN_CHUNK_SIZE;

  if (!Number.isInteger(maxChunkSize) || maxChunkSize < 1) {
    throw new Error("maxChunkSize must be a positive integer");
  }

  if (!Number.isInteger(minChunkSize) || minChunkSize < 0) {
    throw new Error("minChunkSize must be a non-negative integer");
  }

  const initialChunks = paragraphRanges(input).flatMap((paragraph) => splitLargeParagraph(input, paragraph, maxChunkSize));
  const mergedChunks = mergeSmallChunks(input, initialChunks, { maxChunkSize, minChunkSize });
  const chunkCount = mergedChunks.length;

  return mergedChunks.map((chunk, chunkIndex) => ({
    ...chunk,
    chunkIndex,
    chunkCount,
  }));
}

function mergeSmallChunks(
  input: string,
  chunks: Array<Omit<TextChunk, "chunkIndex" | "chunkCount">>,
  options: { maxChunkSize: number; minChunkSize: number },
): Array<Omit<TextChunk, "chunkIndex" | "chunkCount">> {
  if (chunks.length <= 1) {
    return chunks;
  }

  const merged: Array<Omit<TextChunk, "chunkIndex" | "chunkCount">> = [];
  let cursor = 0;

  while (cursor < chunks.length) {
    let start = chunks[cursor].chunkStart;
    let end = chunks[cursor].chunkEnd;

    // Always try to grow chunks up to maxChunkSize.
    while (cursor + 1 < chunks.length) {
      const next = chunks[cursor + 1];
      const mergedLength = next.chunkEnd - start;

      if (mergedLength > options.maxChunkSize) {
        break;
      }

      const currentLength = end - start;

      // Merge if current chunk is too small, or if we can still grow without exceeding max.
      if (currentLength < options.minChunkSize || mergedLength <= options.maxChunkSize) {
        cursor += 1;
        end = next.chunkEnd;
        continue;
      }

      break;
    }

    merged.push({
      chunkStart: start,
      chunkEnd: end,
      content: input.slice(start, end),
    });

    cursor += 1;
  }

  // Avoid tiny final leftovers if possible.
  if (merged.length >= 2) {
    const last = merged[merged.length - 1];
    const prev = merged[merged.length - 2];
    const lastLength = last.chunkEnd - last.chunkStart;

    if (lastLength < options.minChunkSize) {
      const mergedLength = last.chunkEnd - prev.chunkStart;
      if (mergedLength <= options.maxChunkSize) {
        merged.splice(merged.length - 2, 2, {
          chunkStart: prev.chunkStart,
          chunkEnd: last.chunkEnd,
          content: input.slice(prev.chunkStart, last.chunkEnd),
        });
      }
    }
  }

  return merged;
}

function paragraphRanges(input: string): Array<Omit<TextChunk, "chunkIndex" | "chunkCount">> {
  const ranges: Array<Omit<TextChunk, "chunkIndex" | "chunkCount">> = [];
  const paragraphPattern = /\S[\s\S]*?(?=(?:\r?\n\s*){2,}|$)/g;
  let match: RegExpExecArray | null;

  while ((match = paragraphPattern.exec(input)) !== null) {
    const rawContent = match[0];
    const leadingWhitespace = /^\s*/.exec(rawContent)?.[0].length ?? 0;
    const trailingWhitespace = /\s*$/.exec(rawContent)?.[0].length ?? 0;
    const chunkStart = match.index + leadingWhitespace;
    const chunkEnd = match.index + rawContent.length - trailingWhitespace;
    const content = input.slice(chunkStart, chunkEnd);

    if (content.length > 0) {
      ranges.push({ content, chunkStart, chunkEnd });
    }

    if (match[0].length === 0) {
      paragraphPattern.lastIndex += 1;
    }
  }

  return ranges;
}

function splitLargeParagraph(
  input: string,
  paragraph: Omit<TextChunk, "chunkIndex" | "chunkCount">,
  maxChunkSize: number,
): Array<Omit<TextChunk, "chunkIndex" | "chunkCount">> {
  if (paragraph.content.length <= maxChunkSize) {
    return [paragraph];
  }

  const chunks: Array<Omit<TextChunk, "chunkIndex" | "chunkCount">> = [];
  let cursor = paragraph.chunkStart;

  while (cursor < paragraph.chunkEnd) {
    const remaining = paragraph.chunkEnd - cursor;
    let nextEnd = remaining <= maxChunkSize ? paragraph.chunkEnd : cursor + maxChunkSize;

    if (nextEnd < paragraph.chunkEnd) {
      const preferredEnd = findPreferredSplit(input, cursor, nextEnd);
      nextEnd = preferredEnd > cursor ? preferredEnd : nextEnd;
    }

    const chunkStart = skipLeadingWhitespace(input, cursor, nextEnd);
    const chunkEnd = trimTrailingWhitespace(input, chunkStart, nextEnd);

    if (chunkEnd > chunkStart) {
      chunks.push({
        content: input.slice(chunkStart, chunkEnd),
        chunkStart,
        chunkEnd,
      });
    }

    cursor = skipLeadingWhitespace(input, nextEnd, paragraph.chunkEnd);
  }

  return chunks;
}

function findPreferredSplit(input: string, start: number, hardEnd: number): number {
  for (let index = hardEnd; index > start + MIN_SPLIT_SIZE; index -= 1) {
    if (/\s/.test(input[index - 1] ?? "")) {
      return index;
    }
  }

  return hardEnd;
}

function skipLeadingWhitespace(input: string, start: number, end: number): number {
  let index = start;

  while (index < end && /\s/.test(input[index] ?? "")) {
    index += 1;
  }

  return index;
}

function trimTrailingWhitespace(input: string, start: number, end: number): number {
  let index = end;

  while (index > start && /\s/.test(input[index - 1] ?? "")) {
    index -= 1;
  }

  return index;
}

import type sqlite3 from "sqlite3";
import type { Database } from "sqlite";

export type IndexMetadata = Record<string, string>;

export async function ensureIndexMetadata(
  db: Database<sqlite3.Database, sqlite3.Statement>,
  metadata: IndexMetadata,
  label: string,
): Promise<void> {
  await db.exec(`
    CREATE TABLE IF NOT EXISTS index_metadata (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL
    );
  `);

  const rows = await db.all<Array<{ key: string; value: string }>>(`SELECT key, value FROM index_metadata`);

  if (rows.length === 0) {
    const entries = Object.entries(metadata);
    for (const [key, value] of entries) {
      await db.run(`INSERT INTO index_metadata (key, value) VALUES (?, ?)`, key, value);
    }
    return;
  }

  const existing = new Map(rows.map((row) => [row.key, row.value] as const));

  for (const [key, expected] of Object.entries(metadata)) {
    const actual = existing.get(key);
    if (actual === undefined) {
      throw new Error(`${label} metadata mismatch: missing key '${key}' in index_metadata`);
    }

    if (actual !== expected) {
      throw new Error(`${label} metadata mismatch for '${key}': expected '${expected}' but found '${actual}'`);
    }
  }
}

import { describe, expect, it } from "vitest";
import { chunkText } from "../src/shared/chunk-text.js";

describe("chunkText", () => {
  it("returns no chunks for empty or whitespace input", () => {
    expect(chunkText("")).toEqual([]);
    expect(chunkText("   \n\t  ")).toEqual([]);
  });

  it("merges small paragraphs into larger human-readable chunks by default", () => {
    const text = "First paragraph.\n\nSecond paragraph.";
    const chunks = chunkText(text);

    expect(chunks).toHaveLength(1);
    expect(chunks[0]).toMatchObject({
      chunkIndex: 0,
      chunkCount: 1,
    });
    expect(chunks[0].content).toBe(text);
    expect(text.slice(chunks[0].chunkStart, chunks[0].chunkEnd)).toBe(chunks[0].content);
  });

  it("splits long paragraphs into smaller chunks", () => {
    const text = Array.from({ length: 100 }, (_, index) => `word${index}`).join(" ");
    const chunks = chunkText(text, { maxChunkSize: 80, minChunkSize: 0 });

    expect(chunks.length).toBeGreaterThan(1);
    expect(chunks.every((chunk) => chunk.content.length <= 80)).toBe(true);
    for (const chunk of chunks) {
      expect(text.slice(chunk.chunkStart, chunk.chunkEnd)).toBe(chunk.content);
    }
    expect(chunks[0].chunkIndex).toBe(0);
    expect(chunks[chunks.length - 1].chunkIndex).toBe(chunks.length - 1);
    expect(chunks.every((chunk) => chunk.chunkCount === chunks.length)).toBe(true);
  });

  it("allows a small final leftover chunk when it cannot be merged without exceeding maxChunkSize", () => {
    const text = `${"a".repeat(95)}\n\n${"b".repeat(5)}`;
    const chunks = chunkText(text, { maxChunkSize: 100, minChunkSize: 60 });

    expect(chunks).toHaveLength(2);
    expect(chunks[0].content.length).toBeGreaterThanOrEqual(60);
    expect(chunks[1].content.length).toBeLessThan(60);
  });
});

