describe("SqliteVectorStore.search (sqlite-vec KNN)", () => {
  it("returns nearest neighbors ordered by similarity", async () => {
    const store = await makeStore();

    await store.add({
      source: "a",
      content: "doc a",
      embedding: [1, 0],
      taxonomy: { category: "c", taxonomy: "t", metadata: {} },
    });

    await store.add({
      source: "b",
      content: "doc b",
      embedding: [0, 1],
      taxonomy: { category: "c", taxonomy: "t", metadata: {} },
